#!/usr/bin/env python3
# NOTICE: substantially generated by an LLM coding system.

from pathlib import Path
import csv

import requests

BASE = Path(__file__).resolve().parent
OUT_TRAILS = BASE / "dupage-bikeways-trails.csv"
OUT_MILEPOSTS = BASE / "trail-mile-posts.csv"

TRAILS_URL = (
    "https://gis.dupageco.org/arcgis/rest/services/DuDOT/Bikeways_and_Trails/MapServer/0/query"
)
MILEPOSTS_URL = (
    "https://services.arcgis.com/neJvtQ4PXvnQ86MJ/arcgis/rest/services/Mile_Posts/FeatureServer/0/query"
)

HEADERS = {"User-Agent": "data-adventures-dataset-script/1.0"}

TRAIL_COLUMNS = [
    "object_id",
    "feat_id",
    "bike_id",
    "street_name",
    "facility_name",
    "from_ref",
    "to_ref",
    "trail_system",
    "status",
    "class",
    "network_type",
    "facility_type",
    "surface",
    "jurisdiction",
    "township",
    "agreement",
    "width_ft",
    "length_ft",
    "centroid_longitude",
    "centroid_latitude",
]

MILEPOST_COLUMNS = ["fid", "trail", "mile", "longitude", "latitude"]


def fetch_json(url, params):
    resp = requests.get(url, params=params, headers=HEADERS, timeout=60)
    resp.raise_for_status()
    data = resp.json()
    if "error" in data:
        raise RuntimeError(data["error"])
    return data


def fetch_all_features(url, out_fields, extra_params=None):
    params = {
        "where": "1=1",
        "outFields": out_fields,
        "returnGeometry": "true",
        "outSR": "4326",
        "resultOffset": 0,
        "resultRecordCount": 1000,
        "f": "json",
    }
    if extra_params:
        params.update(extra_params)
    features = []
    while True:
        data = fetch_json(url, params)
        batch = data.get("features", [])
        features.extend(batch)
        if not data.get("exceededTransferLimit"):
            break
        params["resultOffset"] += len(batch)
    return features


def polyline_centroid(geometry):
    xs, ys = [], []
    for path in geometry.get("paths", []):
        for x, y in path:
            xs.append(x)
            ys.append(y)
    if not xs:
        return None, None
    return sum(xs) / len(xs), sum(ys) / len(ys)


def fmt(value, decimals=6):
    if value is None:
        return ""
    if isinstance(value, float):
        return f"{value:.{decimals}f}"
    return "" if value is None else str(value)


def build_trail_rows(features):
    rows = []
    for f in features:
        a = f["attributes"]
        cx, cy = polyline_centroid(f.get("geometry") or {})
        rows.append([
            fmt(a.get("OBJECTID")),
            fmt(a.get("FeatID")),
            fmt(a.get("BikeID")),
            fmt(a.get("StName")),
            fmt(a.get("FacName")),
            fmt(a.get("FromRef")),
            fmt(a.get("ToRef")),
            fmt(a.get("SysDes")),
            fmt(a.get("Status")),
            fmt(a.get("Class")),
            fmt(a.get("NetwkType")),
            fmt(a.get("FacType")),
            fmt(a.get("Surface")),
            fmt(a.get("Juris")),
            fmt(a.get("Twp")),
            fmt(a.get("Agrmnt")),
            fmt(a.get("Width")),
            fmt(a.get("Shape.STLength()"), decimals=2),
            fmt(cx),
            fmt(cy),
        ])
    return rows


def build_milepost_rows(features):
    rows = []
    for f in features:
        a = f["attributes"]
        geom = f.get("geometry") or {}
        rows.append([
            fmt(a.get("FID")),
            fmt(a.get("Trail")),
            fmt(a.get("Mile")),
            fmt(geom.get("x")),
            fmt(geom.get("y")),
        ])
    return sorted(rows, key=lambda r: (r[1], float(r[2]) if r[2] else 0))


def write_csv(path, columns, rows):
    with open(path, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(columns)
        writer.writerows(rows)


def main():
    print("Fetching bikeways and trails...")
    trail_fields = "OBJECTID,FeatID,BikeID,StName,FacName,FromRef,ToRef,SysDes,Status,Class,NetwkType,FacType,Surface,Juris,Twp,Agrmnt,Width,Shape.STLength()"
    trail_features = fetch_all_features(TRAILS_URL, trail_fields)
    trail_rows = build_trail_rows(trail_features)
    write_csv(OUT_TRAILS, TRAIL_COLUMNS, trail_rows)
    print(f"  {OUT_TRAILS.name}: {len(trail_rows)} rows")

    print("Fetching trail mile posts...")
    milepost_features = fetch_all_features(MILEPOSTS_URL, "FID,Trail,Mile")
    milepost_rows = build_milepost_rows(milepost_features)
    write_csv(OUT_MILEPOSTS, MILEPOST_COLUMNS, milepost_rows)
    print(f"  {OUT_MILEPOSTS.name}: {len(milepost_rows)} rows")


if __name__ == "__main__":
    main()
